<template>
<div class="office-page sheet-page" v-loading="loading">
  <header class="office-toolbar"><div class="office-actions sheet-heading"><el-button circle title="返回表格列表" @click="router.push('/sheets')"><span class="material-symbols-outlined">arrow_back</span></el-button><h2>{{ title }}</h2><span class="save-status">{{ !canEdit?'只读':saving?'保存中':dirty.size?'未保存 '+dirty.size+' 格':'已保存' }}</span></div><div class="office-actions"><el-button circle title="重新载入" @click="reload"><span class="material-symbols-outlined">refresh</span></el-button><el-button circle title="保存" :loading="saving" :disabled="!dirty.size" @click="save"><span class="material-symbols-outlined">save</span></el-button><el-button title="导入文件" @click="transferMode='import';transferOpen=true"><span class="material-symbols-outlined">upload</span>导入</el-button><el-button title="导出文件" @click="transferMode='export';transferOpen=true"><span class="material-symbols-outlined">download</span>导出</el-button></div></header>
  <div class="sheet-tabs"><el-button v-for="(sheet,i) in sheets" :key="sheet.id" :type="index===i?'primary':'default'" :plain="index!==i" @click="select(i)" @dblclick="rename(i)">{{ sheet.sheetName }}</el-button><el-button v-if="canEdit" circle title="新增工作表" @click="add"><span class="material-symbols-outlined">add</span></el-button><el-button v-if="canEdit&&sheets.length>1" circle title="删除当前工作表" @click="remove"><span class="material-symbols-outlined">delete</span></el-button></div>
  <div class="sheet-tools" role="toolbar" aria-label="单元格格式与分析"><label class="range-label">选区<input v-model="range" aria-label="选区范围" @change="validateRange"/></label><el-button circle title="加粗" :disabled="!canEdit" @click="quickFormat({bl:format(active).bl?0:1})"><b>B</b></el-button><el-button circle title="斜体" :disabled="!canEdit" @click="quickFormat({it:format(active).it?0:1})"><i>I</i></el-button><label class="color-tool" title="文字颜色"><span class="material-symbols-outlined">format_color_text</span><input type="color" aria-label="文字颜色" :disabled="!canEdit" :value="format(active).color||'#1d2129'" @input="quickFormat({color:($event.target as HTMLInputElement).value})"/></label><label class="color-tool" title="背景颜色"><span class="material-symbols-outlined">format_color_fill</span><input type="color" aria-label="背景颜色" :disabled="!canEdit" :value="format(active).bg||'#ffffff'" @input="quickFormat({bg:($event.target as HTMLInputElement).value})"/></label><el-button circle title="合并单元格" :disabled="!canEdit" @click="merge"><span class="material-symbols-outlined">cell_merge</span></el-button><el-button circle title="拆分单元格" :disabled="!canEdit" @click="split"><span class="material-symbols-outlined">splitscreen</span></el-button><el-button @click="openFormat"><span class="material-symbols-outlined">tune</span>格式与批注</el-button><el-button @click="analysisOpen=true"><span class="material-symbols-outlined">bar_chart</span>数据与图表</el-button></div>
  <div class="formula-bar"><strong>{{ active }}</strong><span>fx</span><input aria-label="公式或内容" :value="raw(active)" :readonly="!canEdit" list="sheet-functions" @input="change(active,($event.target as HTMLInputElement).value)" @keydown.enter="save"/><datalist id="sheet-functions"><option v-for="fn in functions" :key="fn" :value="'='+fn+'('"/></datalist><output v-if="raw(active).startsWith('=')" :class="{invalid:display(active).startsWith('#')}">{{ display(active) }}</output></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button size="small" @click="copyPending">复制未保存内容</el-button><el-button size="small" @click="reload">重新载入</el-button></el-alert>
  <div class="sheet-presence"><span :class="{online:connected}">{{ connected?'实时同步':'连接中 · 自动保存仍可用' }}</span><span v-for="peer in livePeers" :key="peer.client">{{ peer.name }} · {{ peer.key }}{{ peer.editing?' 编辑中':'' }}</span><span v-if="remoteNote">{{ remoteNote }}</span></div>
  <div v-if="filter.value" class="filter-summary">筛选 {{ filter.column }} {{ filter.operator==='equals'?'等于':filter.operator==='gt'?'大于':filter.operator==='lt'?'小于':'包含' }} {{ filter.value }}<el-button link @click="filter.value=''">清除</el-button></div>
  <div class="sheet-scroll"><table class="sheet-grid"><thead><tr><th></th><th v-for="col in columns" :key="col">{{ col }}</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row"><th>{{ row }}</th><template v-for="(col,c) in columns" :key="col"><td v-if="!covered(col+row)" :rowspan="format(col+row).mc?.rs||1" :colspan="format(col+row).mc?.cs||1" :style="cellStyle(col+row,row,c)" :class="{selected:inRange(row-1,c),dirty:dirty.has(col+row),invalid:display(col+row).startsWith('#'),peer:peerAt(col+row)}" :title="format(col+row).comment||peerAt(col+row)"><input :aria-label="col+row" :value="editing===col+row?raw(col+row):display(col+row)" :readonly="!canEdit" :style="textStyle(col+row)" :list="format(col+row).type==='dropdown'?'options-'+col+row:undefined" @focus="focus(col+row)" @blur="editing='';save()" @click.shift.prevent="extend(col+row)" @input="change(col+row,($event.target as HTMLInputElement).value)" @keydown.enter="($event.target as HTMLInputElement).blur()" @keydown.esc="($event.target as HTMLInputElement).blur()"/><datalist v-if="format(col+row).type==='dropdown'" :id="'options-'+col+row"><option v-for="value in (format(col+row).options||'').split(',')" :key="value">{{ value }}</option></datalist><span v-if="format(col+row).comment" class="comment-mark"/></td></template></tr></tbody></table></div>
  <footer class="sheet-footer"><el-pagination small layout="prev, pager, next" :page-size="100" :total="rowCount" v-model:current-page="page"/><span>{{ sheets[index]?.sheetName }} · {{ Object.keys(cells).length }} 格 · 选区 {{ range }}</span></footer>

  <el-dialog v-model="formatOpen" title="格式与批注" width="480px" class="sheet-dialog"><el-form label-position="top"><div class="form-pair"><el-form-item label="字体"><el-select v-model="formatDraft.ff"><el-option v-for="font in ['Arial','Microsoft YaHei','SimSun','monospace']" :key="font" :value="font"/></el-select></el-form-item><el-form-item label="字号"><el-input-number v-model="formatDraft.fs" :min="8" :max="48"/></el-form-item></div><el-form-item label="对齐"><el-radio-group v-model="formatDraft.align"><el-radio-button value="left">左</el-radio-button><el-radio-button value="center">中</el-radio-button><el-radio-button value="right">右</el-radio-button></el-radio-group><el-checkbox v-model="formatDraft.border">边框</el-checkbox></el-form-item><el-form-item label="数据类型"><el-select v-model="formatDraft.type"><el-option label="自动" value="auto"/><el-option label="文本" value="text"/><el-option label="数字" value="number"/><el-option label="日期 YYYY-MM-DD" value="date"/><el-option label="下拉列表" value="dropdown"/></el-select></el-form-item><el-form-item v-if="formatDraft.type==='dropdown'" label="下拉选项（英文逗号分隔）"><el-input v-model="formatDraft.options"/></el-form-item><div v-if="formatDraft.type==='number'" class="form-pair"><el-form-item label="最小值（可空）"><el-input v-model="minimum"/></el-form-item><el-form-item label="最大值（可空）"><el-input v-model="maximum"/></el-form-item></div><el-form-item label="条件格式：大于此值时标绿（可空）"><el-input v-model="threshold"/></el-form-item><el-form-item label="批注"><el-input v-model="formatDraft.comment" type="textarea" :rows="3" maxlength="1000"/></el-form-item></el-form><template #footer><el-button @click="formatOpen=false">取消</el-button><el-button type="primary" :disabled="!canEdit" @click="applyFormat">应用到选区</el-button></template></el-dialog>

  <el-dialog v-model="analysisOpen" title="数据与图表" width="760px" class="sheet-dialog"><el-tabs v-model="analysisTab"><el-tab-pane label="排序与筛选" name="sort"><el-form label-position="top"><el-form-item label="排序范围（整行数据，首行标题可排除）"><el-input v-model="sortRange" aria-label="排序范围"/></el-form-item><div v-for="(rule,i) in sortRules" :key="i" class="sort-rule"><el-select v-model="rule.column" aria-label="排序列"><el-option v-for="col in columns" :key="col" :value="col"/></el-select><el-select v-model="rule.descending" aria-label="排序方向"><el-option label="升序" :value="false"/><el-option label="降序" :value="true"/></el-select><el-button circle title="移除排序条件" :disabled="sortRules.length===1" @click="sortRules.splice(i,1)"><span class="material-symbols-outlined">remove</span></el-button></div><el-button :disabled="sortRules.length>=5" @click="sortRules.push({column:'A',descending:false})">添加条件</el-button><el-button type="primary" :disabled="!canEdit" @click="sort">排序并保存</el-button><el-divider/><div class="sort-rule"><el-select v-model="filter.column" aria-label="筛选列"><el-option v-for="col in columns" :key="col" :value="col"/></el-select><el-select v-model="filter.operator" aria-label="筛选条件"><el-option label="包含" value="contains"/><el-option label="等于" value="equals"/><el-option label="大于" value="gt"/><el-option label="小于" value="lt"/></el-select><el-input v-model="filter.value" placeholder="筛选值"/></div><el-checkbox v-model="settings.freezeRow" :disabled="!canEdit" @change="saveSettings">冻结首行</el-checkbox><el-checkbox v-model="settings.freezeColumn" :disabled="!canEdit" @change="saveSettings">冻结首列</el-checkbox></el-form></el-tab-pane><el-tab-pane label="图表" name="charts"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="chartDraft.title"/></el-form-item><div class="form-pair"><el-form-item label="类型"><el-select v-model="chartDraft.type"><el-option v-for="item in chartTypes" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="标签或X轴范围"><el-input v-model="chartDraft.labels"/></el-form-item><el-form-item label="数值或Y轴范围"><el-input v-model="chartDraft.values"/></el-form-item></div><el-button type="primary" :disabled="!canEdit" @click="addChart">添加图表</el-button></el-form><div v-for="chart in currentCharts" :key="chart.id" class="chart-item"><SheetChartCanvas :title="chart.config.title" :type="chart.chartType" :points="chartPoints(chart.config)"/><el-button v-if="canEdit" circle title="删除图表" @click="deleteChart(chart.id)"><span class="material-symbols-outlined">delete</span></el-button></div></el-tab-pane><el-tab-pane label="分组汇总" name="group"><div class="sort-rule"><el-select v-model="groupColumn" aria-label="分组列"><el-option v-for="col in columns" :key="col" :value="col"/></el-select><el-select v-model="valueColumn" aria-label="汇总数值列"><el-option v-for="col in columns" :key="col" :value="col"/></el-select></div><el-table :data="groups"><el-table-column prop="name" label="分组"/><el-table-column prop="count" label="数量"/><el-table-column prop="sum" label="求和"/><el-table-column prop="average" label="平均"/></el-table></el-tab-pane></el-tabs></el-dialog>

  <el-dialog v-model="transferOpen" :title="transferMode==='import'?'导入表格':'导出表格'" width="480px" class="sheet-dialog"><el-form label-position="top"><el-form-item v-if="transferMode==='import'" label="Excel 或 UTF-8 CSV"><input type="file" accept=".xlsx,.xls,.csv" aria-label="选择表格文件" @change="importFile=($event.target as HTMLInputElement).files?.[0]"/></el-form-item><el-form-item v-else label="文件格式"><el-select v-model="exportType"><el-option label="Excel（完整工作簿）" value="xlsx"/><el-option label="CSV（当前工作表）" value="csv"/><el-option label="PDF（当前工作表）" value="pdf"/></el-select></el-form-item><template v-if="transferMode==='import'||exportType!=='xlsx'"><el-form-item label="起始行"><el-input-number v-model="transferStart" :min="1" :max="10000"/></el-form-item><el-form-item label="列映射（可空，例 A,C,B）"><el-input v-model="transferColumns" placeholder="全部列"/></el-form-item></template></el-form><template #footer><el-button @click="transferOpen=false">取消</el-button><el-button type="primary" :loading="transferring" @click="transferFile">{{ transferMode==='import'?'导入为新表格':'下载' }}</el-button></template></el-dialog>
</div>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {getToken} from '@/utils/token'
import {wsClient} from '@/utils/wsClient'
import SheetChartCanvas from './SheetChartCanvas.vue'
type Cell={cellKey:string;content?:string;formula?:string;formatJson?:string;resultValue?:string;rowIndex?:number;colIndex?:number}
const route=useRoute(),router=useRouter(),id=String(route.params.docId),title=ref('表格'),sheets=ref<any[]>([]),index=ref(0),cells=reactive<Record<string,Cell>>({}),baseline=reactive<Record<string,Cell>>({}),dirty=reactive(new Set<string>()),loading=ref(false),saving=ref(false),canEdit=ref(false),error=ref(''),active=ref('A1'),editing=ref(''),range=ref('A1'),page=ref(1)
const functions=['SUM','AVERAGE','MAX','MIN','COUNT','IF','AND','OR','NOT','CONCAT','LEFT','RIGHT','MID','TODAY','NOW','DATE','DATEDIF','VLOOKUP','HLOOKUP','INDEX','MATCH']
const connected=ref(false),remoteNote=ref(''),client=crypto.randomUUID(),name=ref('协作者'),peers=reactive<Record<string,any>>({}),clock=ref(Date.now()),livePeers=computed(()=>Object.values(peers).filter(p=>clock.value-p.time<30000&&p.sheetId===sheets.value[index.value]?.id)),settings=reactive({freezeRow:false,freezeColumn:false})
let timer:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setInterval>|undefined,removeWs:(()=>void)[]=[],savePromise:Promise<boolean>|undefined,refreshPromise:Promise<void>|undefined,disposed=false
const formatOpen=ref(false),formatDraft=reactive<Record<string,any>>({}),minimum=ref(''),maximum=ref(''),threshold=ref(''),analysisOpen=ref(false),analysisTab=ref('sort'),sortRange=ref('A2:C10'),sortRules=reactive([{column:'A',descending:false}]),filter=reactive({column:'A',operator:'contains',value:''}),groupColumn=ref('A'),valueColumn=ref('B')
const charts=ref<any[]>([]),chartDraft=reactive({title:'数据图表',type:'bar',labels:'A2:A6',values:'B2:B6'}),chartTypes=[{label:'柱状图',value:'bar'},{label:'折线图',value:'line'},{label:'饼图',value:'pie'},{label:'散点图',value:'scatter'}],currentCharts=computed(()=>charts.value.filter(c=>c.config.sheetId===sheets.value[index.value]?.id))
const transferOpen=ref(false),transferMode=ref('export'),exportType=ref('xlsx'),transferStart=ref(1),transferColumns=ref(''),importFile=ref<File>(),transferring=ref(false)
const columnCount=computed(()=>Math.max(26,...Object.keys(cells).map(k=>coord(k)[1]+1))),columns=computed(()=>Array.from({length:columnCount.value},(_,i)=>key(0,i).replace(/\d+/,''))),rowCount=computed(()=>Math.max(100,...Object.keys(cells).map(k=>coord(k)[0]+1))),visibleRows=computed(()=>Array.from({length:Math.min(100,rowCount.value-(page.value-1)*100)},(_,i)=>(page.value-1)*100+i+1).filter(row=>!filter.value||row===1||matches(display(filter.column+row))))
const groups=computed(()=>{const result=new Map<string,{name:string;count:number;sum:number;numeric:number}>();for(let row=2;row<=rowCount.value;row++){const label=display(groupColumn.value+row);if(!label)continue;const item=result.get(label)||{name:label,count:0,sum:0,numeric:0};item.count++;const raw=display(valueColumn.value+row),value=Number(raw);if(raw!==''&&Number.isFinite(value)){item.sum+=value;item.numeric++}result.set(label,item)}return [...result.values()].map(g=>({...g,average:g.numeric?(g.sum/g.numeric).toFixed(2):'—'}))})
function key(r:number,c:number){let col='',n=c+1;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26)}return col+(r+1)}
function coord(value:string):[number,number]{const m=/^([A-Z]{1,3})([1-9][0-9]{0,4})$/.exec(value.toUpperCase());if(!m)throw new Error('单元格范围不合法');let col=0;for(const c of m[1]!)col=col*26+c.charCodeAt(0)-64;const row=Number(m[2]);if(row>10000||col>256)throw new Error('最多10000行、256列');return [row-1,col-1]}
function rangeKeys(value=range.value){const parts=value.toUpperCase().split(':'),a=coord(parts[0]!),b=coord(parts[1]||parts[0]!);if(parts.length>2)throw new Error('范围不合法');const keys:string[]=[];for(let r=Math.min(a[0],b[0]);r<=Math.max(a[0],b[0]);r++)for(let c=Math.min(a[1],b[1]);c<=Math.max(a[1],b[1]);c++){if(keys.length>=10000)throw new Error('单次操作最多10000格');keys.push(key(r,c))}return keys}
function validateRange(){try{rangeKeys();range.value=range.value.toUpperCase()}catch(e:any){ElMessage.warning(e.message);range.value=active.value}}
function format(k:string){try{return JSON.parse(cells[k]?.formatJson||'{}')}catch{return {}}}
function raw(k:string){const c=cells[k];return c?.content??(c?.formula?'='+c.formula:'')}
function display(k:string){return dirty.has(k)?raw(k):cells[k]?.resultValue??raw(k)}
function covered(k:string){const mc=format(k).mc;return mc&&!mc.rs}
function inRange(r:number,c:number){try{const p=range.value.toUpperCase().split(':'),a=coord(p[0]!),b=coord(p[1]||p[0]!);return r>=Math.min(a[0],b[0])&&r<=Math.max(a[0],b[0])&&c>=Math.min(a[1],b[1])&&c<=Math.max(a[1],b[1])}catch{return false}}
function matches(value:string){switch(filter.operator){case 'equals':return value===filter.value;case 'gt':return Number(value)>Number(filter.value);case 'lt':return Number(value)<Number(filter.value);default:return value.toLowerCase().includes(filter.value.toLowerCase())}}
function textStyle(k:string){const f=format(k);return {fontWeight:f.bl?'700':'400',fontStyle:f.it?'italic':'normal',fontSize:(f.fs||13)+'px',fontFamily:f.ff||'inherit',color:f.color||'var(--c-text)',textAlign:f.align||'left'}}
function cellStyle(k:string,r:number,c:number){const f=format(k),style:Record<string,string|number>={background:f.bg||'var(--c-surface)'};if(f.threshold!==undefined&&Number(display(k))>Number(f.threshold))style.background='var(--c-success-light)';if(f.border)style.boxShadow='inset 0 0 0 1px var(--c-text-muted)';if(settings.freezeRow&&r===1){style.position='sticky';style.top='30px';style.zIndex=3}if(settings.freezeColumn&&c===0){style.position='sticky';style.left='44px';style.zIndex=r===1?4:2}return style}
function peerAt(k:string){return livePeers.value.filter(p=>p.key===k).map(p=>p.name).join('、')}
function focus(k:string){editing.value=k;active.value=k;range.value=k;cursor(false)}
function extend(k:string){range.value=active.value+':'+k}
function cursor(editing:boolean){if(connected.value)wsClient.send('DOC_CURSOR',{kind:'sheet',client,name:name.value,key:active.value,sheetId:sheets.value[index.value]?.id,editing},id)}
function change(k:string,value:string){if(!canEdit.value)return;cells[k]={...cells[k],cellKey:k,content:value,formula:value.startsWith('=')?value.slice(1):undefined};dirty.add(k);cursor(true);schedule()}
function schedule(){if(timer)clearTimeout(timer);timer=setTimeout(()=>save(),800)}
async function detail(){const r:any=await request.get('/sheet/manage/'+id);title.value=r.data.title;sheets.value=r.data.sheets;index.value=Math.min(index.value,Math.max(0,sheets.value.length-1));Object.assign(settings,JSON.parse(sheets.value[index.value]?.settingsJson||'{}'))}
async function loadCells(reset=false):Promise<void>{if(!sheets.value[index.value])return;if(refreshPromise){await refreshPromise;if(reset)await loadCells(true);return}refreshPromise=readCells(reset);try{await refreshPromise}finally{refreshPromise=undefined}}
async function readCells(reset:boolean){const sheetId=sheets.value[index.value].id;const r:any=await request.get('/sheet/cell/details',{params:{sheetId}});if(sheets.value[index.value]?.id!==sheetId||disposed)return;if(reset){Object.keys(cells).forEach(k=>delete cells[k]);Object.keys(baseline).forEach(k=>delete baseline[k]);dirty.clear()}for(const c of r.data)if(!dirty.has(c.cellKey)){cells[c.cellKey]={...c};baseline[c.cellKey]={...c}}}
async function save():Promise<boolean>{if(timer)clearTimeout(timer);if(savePromise){if(!await savePromise)return false;return dirty.size?save():!error.value}if(!dirty.size)return true;savePromise=doSave();try{return await savePromise}finally{savePromise=undefined}}
async function doSave(){saving.value=true;const sheetId=sheets.value[index.value]?.id;const entries=[...dirty].map(cellKey=>({sheetId,cellKey,content:raw(cellKey),formatJson:cells[cellKey]?.formatJson||'{}',checkConflict:true,expectedContent:baseline[cellKey]?.content||'',expectedFormatJson:baseline[cellKey]?.formatJson||''}));try{await request.put('/sheet/cell/batch',{sheetId,cells:entries});for(const e of entries){baseline[e.cellKey]={cellKey:e.cellKey,content:e.content,formatJson:e.formatJson};if(raw(e.cellKey)===e.content&&(cells[e.cellKey]?.formatJson||'{}')===e.formatJson)dirty.delete(e.cellKey)}error.value='';await loadCells();wsClient.send('SHEET_CELL_UPDATE',{sheetId,client,name:name.value,keys:entries.map(e=>e.cellKey)},id);cursor(false);return true}catch(e:any){error.value='保存失败，修改仍保留在本页：'+e.message;return false}finally{saving.value=false}}
async function reload(){try{if(dirty.size)await ElMessageBox.confirm('当前未保存内容将被放弃，可先复制备份。','重新载入',{type:'warning'});await loadCells(true);error.value=''}catch{}}
async function copyPending(){await navigator.clipboard.writeText(JSON.stringify([...dirty].map(k=>cells[k]),null,2));ElMessage.success('已复制未保存内容')}
function quickFormat(patch:Record<string,any>){if(!canEdit.value)return;try{for(const k of rangeKeys()){cells[k]={...cells[k],cellKey:k,formatJson:JSON.stringify({...format(k),...patch})};dirty.add(k)}schedule()}catch(e:any){ElMessage.warning(e.message)}}
function openFormat(){Object.keys(formatDraft).forEach(k=>delete formatDraft[k]);Object.assign(formatDraft,{ff:'Arial',fs:13,align:'left',type:'auto',border:false,comment:'',...format(active.value)});minimum.value=formatDraft.min===undefined?'':String(formatDraft.min);maximum.value=formatDraft.max===undefined?'':String(formatDraft.max);threshold.value=formatDraft.threshold===undefined?'':String(formatDraft.threshold);formatOpen.value=true}
function applyFormat(){for(const value of [minimum.value,maximum.value,threshold.value])if(value!==''&&!Number.isFinite(Number(value))){ElMessage.warning('规则须为有效数字');return}const patch:Record<string,any>={...formatDraft,min:minimum.value===''?undefined:Number(minimum.value),max:maximum.value===''?undefined:Number(maximum.value),threshold:threshold.value===''?undefined:Number(threshold.value)};delete patch.mc;quickFormat(patch);formatOpen.value=false;save()}
async function merge(){try{const keys=rangeKeys();if(keys.length<2){ElMessage.info('请先选择多个单元格');return}if(keys.some(k=>format(k).mc)){ElMessage.warning('请先拆分已有合并单元格');return}const points=keys.map(coord),r=Math.min(...points.map(p=>p[0])),c=Math.min(...points.map(p=>p[1])),rs=Math.max(...points.map(p=>p[0]))-r+1,cs=Math.max(...points.map(p=>p[1]))-c+1;for(const k of keys){cells[k]={...cells[k],cellKey:k,formatJson:JSON.stringify({...format(k),mc:k===key(r,c)?{r,c,rs,cs}:{r,c}})}}keys.forEach(k=>dirty.add(k));await save()}catch(e:any){ElMessage.warning(e.message)}}
async function split(){const mc=format(active.value).mc;if(!mc)return;for(const k of Object.keys(cells)){const f=format(k);if(f.mc?.r===mc.r&&f.mc?.c===mc.c){delete f.mc;cells[k]={...cells[k],cellKey:k,formatJson:JSON.stringify(f)};dirty.add(k)}}await save()}
async function select(i:number){if(await save()){index.value=i;page.value=1;Object.assign(settings,{freezeRow:false,freezeColumn:false},JSON.parse(sheets.value[i]?.settingsJson||'{}'));await loadCells(true)}}
async function add(){try{const {value}=await ElMessageBox.prompt('名称','新增工作表',{inputValidator:v=>!!v?.trim()&&v.length<=31||'请输入1到31字'});if(!await save())return;await request.post(`/sheet/manage/${id}/sheet`,null,{params:{name:value.trim()}});await detail();index.value=sheets.value.length-1;await loadCells(true)}catch{}}
async function rename(i:number){if(!canEdit.value)return;try{const {value}=await ElMessageBox.prompt('名称','重命名工作表',{inputValue:sheets.value[i].sheetName,inputValidator:v=>!!v?.trim()&&v.length<=31||'请输入1到31字'});if(!await save())return;await request.put(`/sheet/manage/${id}/sheet/${i}/rename`,null,{params:{name:value.trim()}});await detail();await loadCells(true)}catch{}}
async function remove(){try{await ElMessageBox.confirm('删除当前工作表及其内容？','删除工作表',{type:'warning'});if(!await save())return;await request.delete(`/sheet/manage/${id}/sheet/${index.value}`);index.value=0;await detail();await loadCells(true)}catch{}}
async function sort(){try{rangeKeys(sortRange.value);if(!await save())return;await request.post(`/sheet/${id}/sort`,{sheetId:sheets.value[index.value].id,range:sortRange.value.toUpperCase(),rules:sortRules});await loadCells(true);wsClient.send('SHEET_CELL_UPDATE',{client,name:name.value},id);ElMessage.success('排序已保存')}catch(e:any){if(!e.displayed)ElMessage.warning(e.message)}}
async function saveSettings(){await request.put(`/sheet/${id}/settings`,{sheetId:sheets.value[index.value].id,...settings});await detail();wsClient.send('SHEET_CELL_UPDATE',{client,name:name.value,settings:true},id)}
async function loadCharts(){const r:any=await request.get(`/sheet/${id}/charts`);charts.value=r.data.map((c:any)=>({...c,config:JSON.parse(c.configJson||'{}')}))}
function chartPoints(config:any){try{const labels=rangeKeys(config.labels),values=rangeKeys(config.values);return values.slice(0,100).map((k,i)=>({label:display(labels[i]||'')||String(i+1),value:Number(display(k))})).filter(p=>Number.isFinite(p.value))}catch{return []}}
async function addChart(){try{if(rangeKeys(chartDraft.labels).length!==rangeKeys(chartDraft.values).length)throw new Error('标签与数值范围长度须一致');if(!await save())return;await request.post(`/sheet/${id}/charts`,{chartType:chartDraft.type,configJson:JSON.stringify({...chartDraft,sheetId:sheets.value[index.value].id})});await loadCharts();wsClient.send('SHEET_CELL_UPDATE',{client},id)}catch(e:any){if(!e.displayed)ElMessage.warning(e.message)}}
async function deleteChart(chartId:number){await request.delete(`/sheet/${id}/charts/${chartId}`);await loadCharts();wsClient.send('SHEET_CELL_UPDATE',{client},id)}
async function transferFile(){if(!await save())return;transferring.value=true;try{if(transferMode.value==='import'){if(!importFile.value)throw new Error('请选择文件');const form=new FormData();form.append('file',importFile.value);form.append('startRow',String(transferStart.value));form.append('columns',transferColumns.value);const r:any=await request.post('/sheet/import',form,{timeout:60000});transferOpen.value=false;await router.push('/sheets/'+r.data.sheetId);location.reload()}else{const r:any=await request.get(`/sheet/${id}/export`,{params:{format:exportType.value,sheetId:sheets.value[index.value].id,startRow:transferStart.value,columns:transferColumns.value},timeout:60000});const response=await fetch(r.data.downloadUrl);if(!response.ok)throw new Error('下载失败');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=title.value+'.'+exportType.value;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);transferOpen.value=false}}catch(e:any){if(!e.displayed)ElMessage.error(e.message||'传输失败')}finally{transferring.value=false}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.size){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>await save())
onMounted(async()=>{loading.value=true;try{const d:any=await request.get('/document/'+id);canEdit.value=d.data.canEdit===true;await detail();await loadCells(true);await loadCharts();const u:any=await request.get('/user/info');name.value=u.data.nickname||u.data.username||'协作者';wsClient.connect(getToken()||undefined);removeWs.push(wsClient.onStatusChange(ok=>{connected.value=ok;if(ok){wsClient.send('DOC_JOIN',{},id);cursor(false);loadCells().catch(()=>{})}}),wsClient.on('sheet_cell_broadcast',async data=>{if(data.roomId!==id||data.client===client)return;remoteNote.value=(data.name||'协作者')+' 已保存修改';try{await loadCells();if(data.settings)await detail();await loadCharts()}catch(e:any){error.value=e.message}}),wsClient.on('doc_cursor_broadcast',data=>{if(data.roomId===id&&data.kind==='sheet'&&data.client!==client)peers[data.client]={...data,time:Date.now()}}));poll=setInterval(()=>{clock.value=Date.now();cursor(editing.value!=='');if(!connected.value)loadCells().catch(()=>{})},10000);window.addEventListener('beforeunload',beforeUnload)}catch(e:any){error.value=e.message}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;if(timer)clearTimeout(timer);if(poll)clearInterval(poll);cursor(false);wsClient.send('DOC_LEAVE',{},id);removeWs.forEach(fn=>fn());window.removeEventListener('beforeunload',beforeUnload)})
</script>
