0px;padding:0;min-width:120px;width:120px}.sheet-grid th{font-weight:400;background:var(--c-surface-dim);position:sticky;top:0;z-index:5;color:var(--c-text-secondary)}.sheet-grid tbody th,.sheet-grid th:first-child{min-width:44px;width:44px;left:0;z-index:5}.sheet-grid td{position:relative}.sheet-grid input{border:0;outline:0;width:100%;min-width:120px;box-sizing:border-box;padding:6px;height:30px;color:var(--c-text);background:transparent;font:inherit}.sheet-grid td.selected{outline:1px solid var(--c-brand);outline-offset:-1px}.sheet-grid input:focus{outline:2px solid var(--c-brand);outline-offset:-2px}.sheet-grid td.dirty{box-shadow:inset 0 -2px var(--c-warning)}.sheet-grid td.peer{box-shadow:inset 0 0 0 2px var(--c-success)}.invalid{color:var(--c-danger)}.comment-mark{position:absolute;right:1px;top:1px;border-top:6px solid var(--c-warning);border-left:6px solid transparent;pointer-events:none}.sheet-footer{display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap}.form-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.sort-rule{display:flex;gap:8px;align-items:center;margin-bottom:12px}.sort-rule>*{min-width:0}.chart-item{margin-top:16px;border-top:1px solid var(--c-border);padding-top:16px;position:relative}.chart-item>.el-button{position:absolute;right:0;top:12px}.sheet-dialog .el-select{width:100%}.material-symbols-outlined{font-size:20px}.sheet-tools .el-button+.el-button{margin-left:0}.sheet-dialog input[type=file]{max-width:100%}@media(max-width:600px){.sheet-page{height:calc(100dvh - 116px);padding:10px;min-height:600px}.sheet-heading{flex-basis:100%;flex-wrap:wrap}.office-toolbar{gap:8px}.sheet-tools{gap:6px}.sheet-tools .el-button{padding:6px}.save-status{font-size:11px}.form-pair{grid-template-columns:minmax(0,1fr)}.sheet-footer>span{width:100%}.formula-bar output{max-width:25%;padding:0 4px}.sort-rule{flex-wrap:wrap}.sort-rule .el-select{width:calc(50% - 5px)}.sheet-tools :deep(.el-button.is-circle){width:28px;height:28px}.sheet-tools .range-label input{width:80px}}
</style>
